mapper.select:
select  

 order by e.plant_cd, e.equip_cd
 limit #{limit}

mapper.update:
update cms_equip_sec
   set network_yn = #{s.networkYn}, os_nm = #{s.osNm}, os_ver = #{s.osVer}, os_eos_date = #{s.osEosDate},
       last_scan_date = #{s.lastScanDate}, scan_tool = #{s.scanTool}, target_sl = #{s.targetSl}, current_sl = #{s.currentSl},
       usb_ctrl_yn = #{s.usbCtrlYn}, remote_access = #{s.remoteAccess}, remote_text = #{s.remoteText}, review_date = #{s.reviewDate},
       remark = #{s.remark}, row_ver = row_ver + 1, updated_at = now(), updated_by = #{by}
 where equip_id = #{equipId} and row_ver = #{s.rowVer}
